@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=DM+Mono:wght@400;500&display=swap');
:root{--ink:#071322;--paper:#edf3f4;--muted:#a0b0bb;--red:#e4434b;--cyan:#59d5e5;--line:rgba(222,239,244,.19);--mono:'DM Mono',monospace;--display:'Barlow Condensed',Impact,sans-serif}*{box-sizing:border-box}html,body{height:100%;margin:0;background:#071322;color:var(--paper);font-family:var(--mono);overflow:hidden}button{font:inherit;color:inherit;cursor:pointer}#app{position:relative;width:100%;height:100%;min-height:520px;overflow:hidden;background:radial-gradient(ellipse at 68% 35%,#263d55 0,#101f31 44%,#071322 100%);isolation:isolate}#scene{position:absolute;inset:0;width:100%;height:100%;image-rendering:pixelated;z-index:-1}.scanlines{position:absolute;inset:0;pointer-events:none;z-index:5;opacity:.10;background:repeating-linear-gradient(0deg,transparent 0px,transparent 3px,#b6d2d8 4px);mix-blend-mode:soft-light}.topbar{position:absolute;z-index:4;left:5.2%;right:5.2%;top:5%;display:flex;align-items:center;justify-content:space-between;font-size:10px;letter-spacing:.13em;color:#dbe5e8}.brand{font-family:var(--display);font-size:21px;font-weight:600;letter-spacing:.08em}.brand b{font-weight:900;color:#fff}.brand-mark{display:inline-grid;place-items:center;width:27px;height:27px;margin-right:10px;color:var(--red);border:1px solid rgba(228,67,75,.7);font-size:15px;vertical-align:middle}.top-meta{display:flex;align-items:center;gap:8px;color:#aebdc7}.pulse{width:7px;height:7px;border-radius:50%;background:#df5556;box-shadow:0 0 11px #ed5353}.edition{padding:7px 9px;border:1px solid var(--line);margin-left:13px;font-size:9px;letter-spacing:.12em}.screen{position:absolute;inset:0;z-index:2}.title-screen{background:linear-gradient(90deg,rgba(5,14,25,.75) 0%,rgba(5,14,25,.25) 44%,transparent 75%),linear-gradient(0deg,rgba(4,11,20,.75),transparent 30%)}.title-copy{position:absolute;left:11.2%;top:25%;max-width:470px}.eyebrow{font-size:10px;letter-spacing:.23em;color:var(--cyan);font-weight:500}.title-copy h1{font:900 clamp(76px,10.5vw,142px)/.73 var(--display);letter-spacing:-.025em;margin:28px 0 20px;text-shadow:5px 5px 0 rgba(5,15,27,.5)}h1 em{font-style:normal;color:var(--red)}.intro-copy{font-size:12px;color:#c0cbd2;letter-spacing:.015em;margin-bottom:34px}.title-actions{display:flex;gap:12px}.primary,.secondary{min-height:47px;padding:0 20px;border:1px solid var(--red);background:var(--red);font-size:10px;letter-spacing:.1em;font-weight:500;transition:.2s}.primary span,.secondary span{font-size:16px;margin-left:19px}.primary:hover{background:#ff6268;transform:translateY(-2px);box-shadow:0 7px 30px #e4434b42}.secondary{border-color:rgba(255,255,255,.35);background:rgba(9,20,33,.3)}.secondary:hover{border-color:#fff;background:#ffffff14}.tiny-note{margin-top:19px;font-size:8px;letter-spacing:.14em;color:#778a98}.hero-caption{position:absolute;right:9%;bottom:16%;display:flex;gap:14px;align-items:center}.hero-caption>span{font-size:24px;color:var(--red);font-family:var(--display)}.hero-caption div{display:grid;gap:5px}.hero-caption b{font-size:10px;letter-spacing:.14em}.hero-caption small{font-size:9px;color:#9eb0bd}.menu-toggle{position:absolute;right:5.2%;top:13%;border:0;background:none;font-size:20px}.menu-toggle span{font-size:9px;letter-spacing:.12em;margin-left:7px}.version{position:absolute;right:5.2%;bottom:7%;font-size:9px;letter-spacing:.15em;color:#b1c0c7}footer{position:absolute;bottom:2.7%;left:5.2%;right:5.2%;display:flex;justify-content:space-between;color:#8696a2;font-size:8px;letter-spacing:.11em;z-index:3}.hidden{display:none!important}.game-screen{z-index:3}.hud-top{position:absolute;top:5%;left:5%;right:5%;display:flex;justify-content:space-between;align-items:flex-start;gap:16px}.hud-card{min-width:174px;background:#071322bd;border:1px solid var(--line);padding:11px 13px;position:relative}.hud-label{font-size:8px;letter-spacing:.17em;color:#aebdc7}.meter{height:4px;background:#34404b;margin-top:8px;width:132px}.meter i{height:100%;display:block;background:var(--red);width:100%;transition:width .25s}.hud-card>span:last-child{position:absolute;right:12px;top:17px;font-size:10px}.xp-meter i{background:var(--cyan)}.mission-card{padding:9px 14px;text-align:center;background:#0713229c;border-bottom:1px solid #e4434b;min-width:240px}.mission-card strong,.mission-card small{display:block}.mission-card strong{font:600 19px var(--display);letter-spacing:.04em;margin:5px}.mission-card small{font-size:8px;color:#a6b6c0;letter-spacing:.12em}.hud-bottom{position:absolute;bottom:7%;left:5%;right:5%;display:flex;align-items:center;justify-content:space-between;font-size:9px;letter-spacing:.12em}.district-tag,.combo{background:#071322c9;padding:11px 13px;border:1px solid var(--line)}.map-dot{display:inline-block;width:7px;height:7px;background:var(--cyan);border-radius:50%;margin-right:8px;box-shadow:0 0 9px var(--cyan)}.combo{color:var(--cyan)}.combo span{color:white}.web-status{display:flex;gap:9px;align-items:center}.web-status i{display:block;width:74px;height:4px;background:linear-gradient(90deg,var(--cyan) 70%,#34404b 70%)}.pause-button{position:absolute;top:5%;right:1%;font-size:13px;width:34px;height:34px;background:#071322c9;border:1px solid var(--line)}.toast{position:absolute;top:21%;left:50%;transform:translateX(-50%);padding:12px 18px;background:#071322e8;border:1px solid var(--cyan);font-size:10px;letter-spacing:.1em;opacity:0;transition:.25s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1}.dialogue{position:absolute;bottom:14%;left:50%;transform:translateX(-50%);width:min(610px,85vw);padding:17px 20px 14px;background:#071322ed;border-left:3px solid var(--red);box-shadow:0 12px 45px #0008}.speaker{font-size:9px;color:var(--cyan);letter-spacing:.18em}.dialogue p{font-size:12px;line-height:1.6;margin:9px 0 8px}.dialogue button{border:0;background:none;color:#a6b9c3;font-size:8px;letter-spacing:.12em;float:right}.touch-controls{display:none;position:absolute;bottom:13%;left:4%;right:4%;justify-content:space-between;align-items:end;pointer-events:none}.touch-controls button{pointer-events:auto;background:#0a1a2bc2;border:1px solid #b5d7e258;width:52px;height:52px;border-radius:50%;font-size:16px;touch-action:none}.dpad,.action-pad{display:flex;gap:7px;align-items:center}.action-pad{display:grid;grid-template-columns:repeat(2,52px)}.action-pad button{font-size:10px}.action-pad .web-btn{color:var(--cyan);font-size:8px}.overlay-screen{z-index:8;background:rgba(3,10,19,.78);backdrop-filter:blur(8px);display:grid;place-items:center}.panel{position:relative;width:min(760px,88vw);max-height:80vh;overflow:auto;background:linear-gradient(140deg,#13263a,#091522);border:1px solid #8396a044;padding:32px 38px;box-shadow:0 30px 90px #0009}.panel h2{font:800 48px/.9 var(--display);margin:8px 0 24px}.close-button{position:absolute;right:19px;top:15px;border:0;background:none;font-size:25px;color:#b3c2ca}.menu-tabs{display:flex;gap:5px;flex-wrap:wrap;border-bottom:1px solid var(--line);padding-bottom:14px}.menu-tabs button{font-size:8px;letter-spacing:.1em;padding:8px 10px;background:transparent;border:1px solid transparent;color:#99aab5}.menu-tabs button.active,.menu-tabs button:hover{color:white;border-color:#e4434b;background:#e4434b19}.panel-content{min-height:210px;padding-top:20px}.content-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.info-card{padding:14px;background:#ffffff08;border:1px solid #ffffff15}.info-card b{display:block;font:600 19px var(--display);letter-spacing:.03em}.info-card p{font-size:9px;color:#a8b7c0;line-height:1.6;margin:7px 0}.info-card .tag{font-size:8px;color:var(--cyan);letter-spacing:.14em}.info-card button,.inline-action{margin-top:7px;padding:8px 11px;border:1px solid #607988;background:#102338;font-size:8px;letter-spacing:.1em}.info-card button:hover,.inline-action:hover{border-color:var(--cyan)}.chapter-list{display:grid;gap:7px}.chapter-row{display:flex;align-items:center;justify-content:space-between;padding:11px;background:#ffffff08;border:1px solid #ffffff12;font-size:9px;letter-spacing:.08em}.chapter-row small{color:#92a4b0}.chapter-row button{background:#13263a;border:1px solid #647b8d;padding:7px 9px;font-size:8px}.muted{color:#a7b5be;font-size:11px;line-height:1.7}.setting-row{display:flex;align-items:center;justify-content:space-between;padding:13px 0;border-bottom:1px solid var(--line);font-size:10px}.setting-row input[type=range]{accent-color:var(--red)}.pause-panel{width:min(540px,90vw);text-align:center}.pause-panel h2{font-size:62px;margin-bottom:2px}.pause-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:24px 0}.pause-grid button{display:flex;justify-content:space-between;padding:13px 14px;background:#ffffff08;border:1px solid #ffffff1a;text-align:left;font-size:9px;letter-spacing:.08em}.pause-grid button:hover{border-color:var(--red)}.pause-grid button span{font-size:14px;color:var(--cyan)}.controls-hint{font-size:8px;line-height:1.8;color:#8da0ab}.cutscene{z-index:9;background:#071322ed;display:flex;flex-direction:column;justify-content:space-between;padding:5.5% 8%;animation:fadein .5s}.cutscene-top{display:flex;justify-content:space-between;font-size:9px;letter-spacing:.16em}.cutscene-top button{background:none;border:0;color:#a9bac4;font-size:9px;letter-spacing:.12em}.cutscene-text{max-width:620px;margin:0 auto;text-align:center}.cutscene-text h2{font:800 clamp(42px,8vw,82px)/.9 var(--display);margin:14px 0}.cutscene-text>p:not(.eyebrow){color:#bdc8ce;font-size:12px;line-height:1.8;min-height:35px}.cutscene-text button{margin-top:22px}.scene-progress{height:2px;background:#283744}.scene-progress i{height:100%;width:0;display:block;background:var(--red);transition:width .4s}.ending-panel{text-align:center}.ending-panel .primary,.ending-panel .secondary{margin:8px}.reward-line{font-size:10px;color:var(--cyan);letter-spacing:.1em;margin:24px}.ending-panel h2{font-size:56px}.ending-panel .muted{max-width:460px;margin:0 auto}@keyframes fadein{from{opacity:0}to{opacity:1}}
@media(max-width:700px){.topbar{top:3%;left:5%;right:5%}.top-meta{font-size:8px}.edition{display:none}.brand{font-size:18px}.title-copy{left:8%;top:24%;max-width:80%}.title-copy h1{font-size:clamp(72px,19vw,112px)}.hero-caption{right:7%;bottom:22%}.title-actions{flex-wrap:wrap}.primary,.secondary{min-height:44px;padding:0 13px;font-size:9px}.title-actions .primary span,.title-actions .secondary span{margin-left:8px}.menu-toggle{top:11%;right:5%}.hud-top{top:3%;left:3%;right:3%;gap:5px;align-items:start}.hud-card{padding:8px;min-width:95px}.meter{width:65px}.hud-card>span:last-child{right:6px;top:15px;font-size:8px}.mission-card{min-width:0;flex:1;padding:7px 4px}.mission-card strong{font-size:15px}.mission-card small{font-size:7px}.pause-button{top:12%;right:3%}.hud-bottom{bottom:3%;left:3%;right:3%;font-size:7px}.district-tag,.combo{padding:8px}.web-status i{width:42px}.touch-controls{display:flex;bottom:10%}.dialogue{bottom:25%;width:90vw;padding:13px}.panel{padding:27px 19px;max-height:86vh;width:92vw}.panel h2{font-size:40px}.menu-tabs{gap:2px}.menu-tabs button{font-size:7px;padding:7px 6px}.content-grid{grid-template-columns:1fr}.panel-content{min-height:140px}.pause-panel{width:92vw}.pause-grid{gap:6px}.pause-grid button{font-size:8px;padding:11px 9px}.controls-hint{font-size:7px}.cutscene{padding:8% 6%}.cutscene-text h2{font-size:50px}footer{font-size:6px;bottom:1.4%}footer span:last-child{display:none}.version{right:5%;bottom:5%}}
@media(max-height:650px){.title-copy{top:20%}.title-copy h1{margin:17px 0}.intro-copy{margin-bottom:20px}.panel{max-height:90vh}.title-screen .hero-caption{bottom:10%}}

(() => {
'use strict';
const canvas=document.querySelector('#scene'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const stages=[
 {title:'A caçada ao chefão',district:"HELL'S KITCHEN",kind:'combat',target:4,desc:'Desmonte a operação criminosa e enfrente o chefão.'},
 {title:'Uma nova ameaça',district:'CHINATOWN',kind:'combat',target:5,desc:'Siga as pistas e impeça os mascarados de fugir.'},
 {title:'Segredos da cidade',district:'GREENWICH',kind:'rescue',target:3,desc:'Investigue os esconderijos e resgate pessoas em perigo.'},
 {title:'O inventor',district:'MIDTOWN',kind:'collect',target:4,desc:'Recolha componentes perdidos para o laboratório.'},
 {title:'Cidade em perigo',district:'UPPER WEST SIDE',kind:'combat',target:6,desc:'Proteja os moradores durante a fuga dos criminosos.'},
 {title:'Aliança sombria',district:'FINANCIAL DISTRICT',kind:'boss',target:1,desc:'Enfrente os seis líderes da conspiração.'},
 {title:'Caos em Nova York',district:'CENTRAL PARK',kind:'rescue',target:5,desc:'Resgate civis e recupere o controle das ruas.'},
 {title:'A batalha final',district:'BROOKLYN BRIDGE',kind:'boss',target:1,desc:'Encerre a ameaça no alto da ponte.'},
 {title:'Um novo dia',district:'MANHATTAN',kind:'free',target:1,desc:'A cidade respira. Seu próximo capítulo começa agora.'}
];
const sideMissions=[['Emergência no beco','Resgate três civis presos no beco.','+120 XP'],['Fuga pela avenida','Intercepte a moto antes que alcance a ponte.','+160 XP'],['Sinal no telhado','Investigue o transmissor escondido nos telhados.','+100 XP'],['Cofre abandonado','Recupere suprimentos roubados do bairro.','+140 XP']];
const suits=[['Vermelho urbano','Traje clássico com detalhes em azul.','Começa desbloqueado','✦'],['Aranha noturna','Tons escuros para se mover sem ser visto.','Complete o capítulo 2','◈'],['Pulso neon','Linhas elétricas para noites chuvosas.','Alcance o nível 3','⚡'],['Guardião de aço','Armadura leve feita no laboratório.','Complete o capítulo 5','⬡']];
const chapters=['A caçada ao chefão','Uma nova ameaça','Segredos da cidade','O inventor','Cidade em perigo','Aliança sombria','Caos em Nova York','A batalha final','Um novo dia'];
const defaults={chapter:0,unlocked:0,xp:0,level:1,health:100,completed:[],suit:0,skills:[],rescues:0,crimes:0,collectibles:0,score:0,muted:false,volume:.24,free:false};
let save=loadSave(),screen='title',W=0,H=0,dpr=1,last=0,world=0,cam=0,player={x:180,y:0,vy:0,ground:true,face:1,attack:0,dodge:0,web:100,invuln:0,anim:0},enemies=[],particles=[],rain=[],keys={},gameTime=0,heroHealth=100,combo=0,objectiveCount=0,dialogues=[],dialogueIndex=0,cutTimer=0,sceneLines=[],bossHp=0,bossMax=0,missionStartX=0,menuOrigin='title',activeTab='chapters',audio=null,toastTimer=0;
function loadSave(){try{return {...defaults,...JSON.parse(localStorage.getItem('citywatch-save')||'{}')}}catch{return {...defaults}}}
function saveGame(){save.health=heroHealth;localStorage.setItem('citywatch-save',JSON.stringify(save));showToast('PROGRESSO SALVO');}
function persist(){localStorage.setItem('citywatch-save',JSON.stringify(save));}
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);}
addEventListener('resize',resize);resize();
function audioCtx(){if(!audio){try{audio=new (window.AudioContext||window.webkitAudioContext)()}catch{}}if(audio?.state==='suspended')audio.resume();}
function tone(freq=440,dur=.08,type='square',vol=.04){if(save.muted)return;audioCtx();if(!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol*(save.volume||.24),audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur);}
function showToast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');toastTimer=2.1;}
function stage(){return stages[Math.min(save.chapter,8)]}
function setScreen(name){screen=name;$('#titleScreen').classList.toggle('hidden',name!=='title');$('#gameScreen').classList.toggle('hidden',!['game','dialogue'].includes(name));$('#menuScreen').classList.toggle('hidden',name!=='menu');$('#pauseScreen').classList.toggle('hidden',name!=='pause');$('#cutscene').classList.toggle('hidden',name!=='cutscene');$('#endScreen').classList.toggle('hidden',name!=='end');}
function enterGame(){setScreen('game');heroHealth=save.health||100;heroHealth=Math.min(100,heroHealth);world=0;cam=0;player.x=180;player.y=0;player.vy=0;player.ground=true;missionStartX=0;objectiveCount=0;combo=0;spawnWave();updateHud();}
function spawnWave(){const s=stage();enemies=[];if(s.kind==='boss'){bossMax=save.chapter===7?12:9;bossHp=bossMax;enemies.push(makeEnemy(570,true));showToast('CHEFE DETECTADO · PREPARE-SE');}else if(s.kind==='free'){for(let i=0;i<4;i++)enemies.push(makeEnemy(520+i*190,false));}else{for(let i=0;i<Math.max(4,s.target+1);i++)enemies.push(makeEnemy(430+i*230,false));}}
function makeEnemy(x,boss){return {x,y:0,hp:boss?bossMax:1,boss,attack:0,stun:0,face:-1,phase:0,hit:false};}
function startChapter(n=save.chapter){save.chapter=Math.max(0,Math.min(8,n));save.unlocked=Math.max(save.unlocked,save.chapter);persist();$('#titleChapter').textContent=String(save.chapter+1).padStart(2,'0');sceneLines=getSceneLines(save.chapter);dialogueIndex=0;$('#sceneChapter').textContent=`CAPÍTULO ${String(save.chapter+1).padStart(2,'0')} · ${stage().district}`;$('#sceneTitle').textContent=sceneLines[0][0];$('#sceneLine').textContent=sceneLines[0][1];$('#sceneProgress').style.width='0%';setScreen('cutscene');cutTimer=0;tone(220,.45,'sawtooth',.04);}
function getSceneLines(n){const s=stages[n];return [[s.title,`A noite cai sobre ${s.district}. Um chamado corta o silêncio.`,`O vigia ajusta as luvas e dispara para o alto.`,s.desc]];}
function advanceScene(){if(screen!=='cutscene')return;if(cutTimer<sceneLines.length-1){cutTimer++;$('#sceneTitle').textContent=sceneLines[cutTimer][0];$('#sceneLine').textContent=sceneLines[cutTimer][1];$('#sceneProgress').style.width=`${cutTimer/(sceneLines.length-1)*100}%`;tone(360,.07);}else{enterGame();showToast(`CAPÍTULO ${save.chapter+1} · ${stage().title.toUpperCase()}`);}}
$('#sceneNext').onclick=advanceScene;$('#skipScene').onclick=()=>enterGame();
$('#newGame').onclick=()=>{audioCtx();save={...defaults};persist();startChapter(0);};$('#continueGame').onclick=()=>{audioCtx();startChapter(save.chapter||0);};$('#continueGame').disabled=!localStorage.getItem('citywatch-save');$('#openMenu').onclick=()=>openMenu('title');$('#closeMenu').onclick=()=>setScreen(menuOrigin==='pause'?'pause':menuOrigin==='game'?'game':'title');
$('#pauseButton').onclick=()=>pauseGame();$('#dialogueNext').onclick=nextDialogue;$('#nextMission').onclick=()=>{if(save.chapter<8){startChapter(save.chapter+1);}else{save.free=true;save.chapter=8;persist();enterGame();showToast('MODO LIVRE DESBLOQUEADO');}};$('#backToCity').onclick=()=>{save.free=true;persist();enterGame();};
function pauseGame(){if(screen==='game'){setScreen('pause');tone(160,.12);}else if(screen==='pause')setScreen('game');}
addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowleft','arrowright','arrowup','arrowdown'].includes(k))e.preventDefault();keys[k]=true;if(k==='escape'||k==='p'){if(screen==='game'||screen==='pause')pauseGame();else if(screen==='menu')setScreen(menuOrigin==='game'?'game':'title');}if(k==='enter'&&screen==='cutscene')advanceScene();if(k==='j'||k==='z')act('attack');if(k==='k'||k==='x')act('web');if(k==='l'||k==='c')act('dodge');if(k===' '||k==='w'||k==='arrowup')act('jump');});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
$$('.touch-controls button').forEach(b=>{const action=b.dataset.action;const down=e=>{e.preventDefault();b.setPointerCapture?.(e.pointerId);if(action==='left'||action==='right')keys[action==='left'?'a':'d']=true;else act(action);};const up=()=>{if(action==='left'||action==='right')keys[action==='left'?'a':'d']=false;};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);});
function act(type){if(screen!=='game')return;audioCtx();if(type==='jump'&&player.ground){player.vy=-520;player.ground=false;burst(player.x,groundY()-18,'#d7f0f3',5);tone(290,.08,'square');}if(type==='attack'&&player.attack<=0){player.attack=.25;player.anim+=1;hitNearby(false);tone(110,.07,'sawtooth',.06);}if(type==='web'&&player.web>=22){player.web-=22;hitNearby(true);for(let i=0;i<8;i++)particles.push({x:player.x+cam+player.face*18,y:groundY()-30,vx:player.face*(60+Math.random()*180),vy:-80+Math.random()*150,life:.45,color:'#dffcff',size:2});tone(660,.1,'triangle');}if(type==='dodge'&&player.dodge<=0){player.dodge=.38;player.invuln=.5;player.x+=player.face*34;tone(190,.08,'triangle');}}
function hitNearby(web){let target=enemies.filter(e=>Math.abs(e.x-player.x)<(e.boss?118:90)).sort((a,b)=>Math.abs(a.x-player.x)-Math.abs(b.x-player.x))[0];if(!target){if(web)showToast('TEIA LANÇADA');return;}target.face=target.x>player.x?-1:1;target.stun=web?1.8:.35;if(target.boss){target.hp-=web?1:1;bossHp=target.hp;if(target.hp<=0){target.dead=true;}}else{target.hp=0;target.dead=true;objectiveCount++;combo++;save.score+=100;save.xp+=35;save.crimes++;if(combo%4===0)showToast(`${combo} ACERTOS · COMBO!`);burst(target.x,groundY()-20,'#ffb554',12);tone(90,.12,'square',.07);}if(web)showToast(target.boss?'CHEFE ATORDOADO':'INIMIGO PRESO');checkMission();}
function burst(x,y,color,n){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*190,vy:(Math.random()-.8)*160,life:.3+Math.random()*.4,color,size:2+Math.random()*3});}
function groundY(){return Math.min(H*.73,Math.max(H*.61,470*H/720));}
