(() => {
'use strict';
const canvas=document.querySelector('#scene'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const stages=[
 {title:'A caçada ao chefão',district:"HELL'S KITCHEN",kind:'combat',target:4,desc:'Desmonte a operação criminosa e enfrente o chefão.'},
 {title:'Uma nova ameaça',district:'CHINATOWN',kind:'combat',target:5,desc:'Siga as pistas e impeça os mascarados de fugir.'},
 {title:'Segredos da cidade',district:'GREENWICH',kind:'rescue',target:3,desc:'Investigue os esconderijos e resgate pessoas em perigo.'},
 {title:'O inventor',district:'MIDTOWN',kind:'collect',target:4,desc:'Recolha componentes perdidos para o laboratório.'},
 {title:'Cidade em perigo',district:'UPPER WEST SIDE',kind:'combat',target:6,desc:'Proteja os moradores durante a fuga dos criminosos.'},
 {title:'Aliança sombria',district:'FINANCIAL DISTRICT',kind:'boss',target:1,desc:'Enfrente os seis líderes da conspiração.'},
 {title:'Caos em Nova York',district:'CENTRAL PARK',kind:'rescue',target:5,desc:'Resgate civis e recupere o controle das ruas.'},
 {title:'A batalha final',district:'BROOKLYN BRIDGE',kind:'boss',target:1,desc:'Encerre a ameaça no alto da ponte.'},
 {title:'Um novo dia',district:'MANHATTAN',kind:'free',target:1,desc:'A cidade respira. Seu próximo capítulo começa agora.'}
];
const sideMissions=[['Emergência no beco','Resgate três civis presos no beco.',120],['Fuga pela avenida','Intercepte a moto antes que alcance a ponte.',160],['Sinal no telhado','Investigue o transmissor escondido nos telhados.',100],['Cofre abandonado','Recupere suprimentos roubados do bairro.',140]];
const suits=[['Vermelho urbano','Traje clássico com detalhes em azul.','Começa desbloqueado','✦'],['Aranha noturna','Tons escuros para se mover sem ser visto.','Complete o capítulo 2','◈'],['Pulso neon','Linhas elétricas para noites chuvosas.','Alcance o nível 3','⚡'],['Guardião de aço','Armadura leve feita no laboratório.','Complete o capítulo 5','⬡']];
const defaults={chapter:0,unlocked:0,xp:0,level:1,health:100,completed:[],suit:0,skills:[],rescues:0,crimes:0,collectibles:0,score:0,muted:false,volume:.24,free:false};
let save=loadSave(),screen='title',W=0,H=0,dpr=1,last=0,world=0,cam=0,activeSide=null,player={x:180,y:0,vy:0,ground:true,face:1,attack:0,dodge:0,web:100,invuln:0,anim:0},enemies=[],particles=[],rain=[],keys={},gameTime=0,heroHealth=100,combo=0,objectiveCount=0,cutTimer=0,sceneLines=[],bossHp=0,bossMax=0,audio=null,toastTimer=0,menuOrigin='title',activeTab='chapters';
function loadSave(){try{return {...defaults,...JSON.parse(localStorage.getItem('citywatch-save')||'{}')}}catch{return {...defaults}}}
function persist(){localStorage.setItem('citywatch-save',JSON.stringify(save))}function saveGame(){save.health=heroHealth;persist();showToast('PROGRESSO SALVO')}
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
function audioCtx(){if(!audio){try{audio=new(window.AudioContext||window.webkitAudioContext)()}catch{}}if(audio?.state==='suspended')audio.resume()}
function tone(freq=440,dur=.08,type='square',vol=.04){if(save.muted)return;audioCtx();if(!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol*(save.volume||.24),audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur)}
function showToast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');toastTimer=2.1}function stage(){return stages[Math.min(save.chapter,8)]}
function setScreen(name){screen=name;$('#titleScreen').classList.toggle('hidden',name!=='title');$('#gameScreen').classList.toggle('hidden',!['game','dialogue'].includes(name));$('#menuScreen').classList.toggle('hidden',name!=='menu');$('#pauseScreen').classList.toggle('hidden',name!=='pause');$('#cutscene').classList.toggle('hidden',name!=='cutscene');$('#endScreen').classList.toggle('hidden',name!=='end')}
function enterGame(){activeSide=null;setScreen('game');heroHealth=save.health||100;heroHealth=Math.min(100,heroHealth);world=0;cam=0;player.x=180;player.y=0;player.vy=0;player.ground=true;objectiveCount=0;combo=0;spawnWave();updateHud()}
function spawnWave(){const s=stage();enemies=[];if(s.kind==='boss'){bossMax=save.chapter===7?12:9;bossHp=bossMax;enemies.push(makeEnemy(570,true))}else{for(let i=0;i<Math.max(4,s.target+1);i++)enemies.push(makeEnemy(430+i*230,false))}}
function makeEnemy(x,boss){return{x,y:0,hp:boss?bossMax:1,boss,attack:0,stun:0,face:-1,phase:0,hit:false}}
function getSceneLines(n){const s=stages[n];return[[s.title,`A noite cai sobre ${s.district}. Um chamado corta o silêncio.`],['O vigia da cidade',`O herói ajusta as luvas e dispara para o alto. ${s.desc}`]]}
function startChapter(n=save.chapter){save.chapter=Math.max(0,Math.min(8,n));save.unlocked=Math.max(save.unlocked,save.chapter);persist();$('#titleChapter').textContent=String(save.chapter+1).padStart(2,'0');sceneLines=getSceneLines(save.chapter);cutTimer=0;$('#sceneChapter').textContent=`CAPÍTULO ${String(save.chapter+1).padStart(2,'0')} · ${stage().district}`;$('#sceneTitle').textContent=sceneLines[0][0];$('#sceneLine').textContent=sceneLines[0][1];$('#sceneProgress').style.width='0%';setScreen('cutscene');tone(220,.45,'sawtooth',.04)}
function advanceScene(){if(screen!=='cutscene')return;if(cutTimer<sceneLines.length-1){cutTimer++;$('#sceneTitle').textContent=sceneLines[cutTimer][0];$('#sceneLine').textContent=sceneLines[cutTimer][1];$('#sceneProgress').style.width=`${cutTimer/(sceneLines.length-1)*100}%`;tone(360,.07)}else{enterGame();showToast(`CAPÍTULO ${save.chapter+1} · ${stage().title.toUpperCase()}`)}}
$('#sceneNext').onclick=advanceScene;$('#skipScene').onclick=()=>enterGame();$('#newGame').onclick=()=>{audioCtx();save={...defaults};persist();startChapter(0)};$('#continueGame').onclick=()=>{audioCtx();startChapter(save.chapter||0)};$('#continueGame').disabled=!localStorage.getItem('citywatch-save');$('#openMenu').onclick=()=>openMenu('title');$('#closeMenu').onclick=()=>setScreen(menuOrigin==='pause'?'pause':menuOrigin==='game'?'game':'title');
$('#pauseButton').onclick=()=>pauseGame();$('#dialogueNext').onclick=()=>{};$('#nextMission').onclick=()=>{if(save.chapter<8)startChapter(save.chapter+1);else{save.free=true;persist();enterGame();showToast('MODO LIVRE DESBLOQUEADO')}};$('#backToCity').onclick=()=>{save.free=true;persist();enterGame()};
function pauseGame(){if(screen==='game'){setScreen('pause');tone(160,.12)}else if(screen==='pause')setScreen('game')}
addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowleft','arrowright','arrowup','arrowdown'].includes(k))e.preventDefault();keys[k]=true;if(k==='escape'||k==='p'){if(screen==='game'||screen==='pause')pauseGame();else if(screen==='menu')setScreen(menuOrigin==='game'?'game':'title')}if(k==='enter'&&screen==='cutscene')advanceScene();if(k==='j'||k==='z')act('attack');if(k==='k'||k==='x')act('web');if(k==='l'||k==='c')act('dodge');if(k===' '||k==='w'||k==='arrowup')act('jump')});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
$$('.touch-controls button').forEach(b=>{const a=b.dataset.action,down=e=>{e.preventDefault();if(a==='left'||a==='right')keys[a==='left'?'a':'d']=true;else act(a)},up=()=>{if(a==='left'||a==='right')keys[a==='left'?'a':'d']=false};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up)});
function groundY(){return Math.min(H*.73,Math.max(H*.61,470*H/720))}
function act(type){if(screen!=='game')return;audioCtx();if(type==='jump'&&player.ground){player.vy=-520;player.ground=false;burst(player.x+cam,groundY()-18,'#d7f0f3',5);tone(290,.08)}if(type==='attack'&&player.attack<=0){player.attack=.25;hitNearby(false);tone(110,.07,'sawtooth',.06)}if(type==='web'&&player.web>=22){player.web-=22;hitNearby(true);for(let i=0;i<8;i++)particles.push({x:player.x+cam+player.face*18,y:groundY()-30,vx:player.face*(60+Math.random()*180),vy:-80+Math.random()*150,life:.45,color:'#dffcff',size:2});tone(660,.1,'triangle')}if(type==='dodge'&&player.dodge<=0){player.dodge=.38;player.invuln=.5;player.x+=player.face*34;tone(190,.08,'triangle')}}
function hitNearby(web){const t=enemies.filter(e=>!e.dead&&Math.abs(e.x-player.x)<(e.boss?118:90)).sort((a,b)=>Math.abs(a.x-player.x)-Math.abs(b.x-player.x))[0];if(!t){if(web)showToast('TEIA LANÇADA');return}t.face=t.x>player.x?-1:1;t.stun=web?1.8:.35;if(t.boss){t.hp--;bossHp=t.hp;if(t.hp<=0)t.dead=true}else{t.dead=true;objectiveCount++;combo++;save.score+=100;save.xp+=35;save.crimes++;if(combo%4===0)showToast(`${combo} ACERTOS · COMBO!`);burst(t.x+cam,groundY()-20,'#ffb554',12);tone(90,.12,'square',.07)}if(web)showToast(t.boss?'CHEFE ATORDOADO':'INIMIGO PRESO');checkMission()}
function burst(x,y,color,n){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*190,vy:(Math.random()-.8)*160,life:.3+Math.random()*.4,color,size:2+Math.random()*3})}
function updateHud(){const s=stage();$('#healthFill').style.width=`${Math.max(0,heroHealth)}%`;$('#healthText').textContent=Math.ceil(heroHealth);$('#levelText').textContent=String(save.level).padStart(2,'0');$('#xpText').textContent=`${save.xp} XP`;$('#xpFill').style.width=`${save.xp%300/3}%`;$('#missionName').textContent=`CAPÍTULO ${String(save.chapter+1).padStart(2,'0')} · ${s.title.toUpperCase()}`;$('#objective').textContent=activeSide?`${activeSide.title} · ${objectiveCount}/${activeSide.target}`:s.kind==='boss'?`Derrote o chefe · ${Math.max(0,bossHp)} HP`:s.kind==='rescue'?`Resgate pessoas · ${Math.min(objectiveCount,s.target)}/${s.target}`:s.kind==='collect'?`Recupere componentes · ${Math.min(objectiveCount,s.target)}/${s.target}`:`Derrote os criminosos · ${Math.min(objectiveCount,s.target)}/${s.target}`;$('#districtName').textContent=s.district;$('#combo').innerHTML=`✦ <span>${combo}</span> SEQUÊNCIA`;$('#webFill').style.background=`linear-gradient(90deg,#59d5e5 ${player.web}%,#34404b ${player.web}%)`}
function checkMission(){updateHud();const s=stage(),target=activeSide?activeSide.target:s.target;if((s.kind==='boss'&&!activeSide&&bossHp<=0)||(s.kind!=='boss'&&objectiveCount>=target)||activeSide&&objectiveCount>=target)finishMission()}
function finishMission(){if(screen!=='game')return;if(activeSide){save.xp+=activeSide.reward;save.score+=activeSide.reward;save.completed.push(`side-${activeSide.id}`);save.level=Math.min(20,1+Math.floor(save.xp/300));persist();$('#endTitle').textContent='BAIRRO PROTEGIDO.';$('#endMessage').textContent=`${activeSide.title} concluída. A vizinhança agradece.`;$('#rewardLine').textContent=`+ ${activeSide.reward} XP　·　MISSÃO SECUNDÁRIA`;$('#nextMission').textContent='VOLTAR À CIDADE　↗';$('#backToCity').classList.add('hidden');setScreen('end');return}const idx=save.chapter;if(!save.completed.includes(idx))save.completed.push(idx);save.unlocked=Math.max(save.unlocked,Math.min(8,idx+1));save.xp+=200;save.level=Math.min(20,1+Math.floor(save.xp/300));heroHealth=Math.min(100,heroHealth+25);save.health=heroHealth;save.collectibles++;persist();$('#endTitle').textContent=idx===8?'A CIDADE É SUA.':'BOA, VIGIA.';$('#endMessage').textContent=idx===8?'Sua história está apenas começando. Explore Manhattan e ajude quem precisar.':`${stages[idx].desc} A cidade respira um pouco mais tranquila esta noite.`;$('#rewardLine').textContent=`+ 200 XP　·　+ 1 FICHA　·　NÍVEL ${save.level}`;$('#nextMission').textContent=idx===8?'ENTRAR NO MODO LIVRE　↗':'PRÓXIMO CAPÍTULO　↗';setScreen('end');tone(520,.4,'triangle',.05)}

function openMenu(origin='title',tab='chapters'){menuOrigin=origin;activeTab=tab;setScreen('menu');renderMenu()}
const tabs=[['chapters','CAPÍTULOS'],['missions','MISSÕES'],['suits','TRAJES'],['skills','HABILIDADES'],['map','MAPA'],['stats','ESTATÍSTICAS'],['settings','AJUSTES'],['credits','CRÉDITOS']];
function renderMenu(){const tabsEl=$('#menuTabs');tabsEl.innerHTML='';tabs.forEach(([id,label])=>{const b=document.createElement('button');b.textContent=label;b.className=id===activeTab?'active':'';b.onclick=()=>{activeTab=id;renderMenu()};tabsEl.append(b)});$('#panelTitle').textContent=({chapters:'CAPÍTULOS',missions:'MISSÕES',suits:'TRAJES',skills:'HABILIDADES',map:'NOVA YORK',stats:'SEU LEGADO',settings:'AJUSTES',credits:'CRÉDITOS'})[activeTab];const c=$('#panelContent');
if(activeTab==='chapters')c.innerHTML=`<div class="chapter-list">${chapters.map((name,i)=>`<div class="chapter-row"><span>${String(i+1).padStart(2,'0')}　${name.toUpperCase()}</span><small>${save.completed.includes(i)?'CONCLUÍDO':i<=save.unlocked?'DISPONÍVEL':'BLOQUEADO'}</small><button data-chapter="${i}" ${i>save.unlocked?'disabled':''}>${i<=save.unlocked?'JOGAR':'🔒'}</button></div>`).join('')}</div>`;
else if(activeTab==='missions')c.innerHTML=`<div class="content-grid">${sideMissions.map((m,i)=>{const done=save.completed.includes(`side-${i}`);return `<article class="info-card"><span class="tag">ATIVIDADE ${String(i+1).padStart(2,'0')} · ${done?'CONCLUÍDA':'DISPONÍVEL'}</span><b>${m[0]}</b><p>${m[1]}</p><button data-side="${i}" ${done?'disabled':''}>${done?'CONCLUÍDA':`ACEITAR · +${m[2]} XP`}</button></article>`}).join('')}</div>`;
else if(activeTab==='suits')c.innerHTML=`<div class="content-grid">${suits.map((s,i)=>{const unlocked=i===0||save.completed.includes(1)&&i===1||save.level>=3&&i===2||save.completed.includes(4)&&i===3;return `<article class="info-card"><span class="tag">${s[3]}　${i===save.suit?'EQUIPADO':unlocked?'DESBLOQUEADO':'BLOQUEADO'}</span><b>${s[0]}</b><p>${s[1]} ${unlocked?'':`· ${s[2]}`}</p><button data-suit="${i}" ${unlocked?'':'disabled'}>${i===save.suit?'EM USO':unlocked?'EQUIPAR':'REQUISITO PENDENTE'}</button></article>`}).join('')}</div>`;
else if(activeTab==='skills'){const skills=[['Punhos firmes','Ataques causam dano extra.','fight'],['Teia elástica','Recupera teia mais rápido.','web'],['Passo fantasma','Esquiva dura mais tempo.','dodge'],['Foco total','Mais vida ao concluir missões.','focus']];c.innerHTML=`<p class="muted">Pontos de habilidade disponíveis: <b>${Math.max(0,save.level-1-save.skills.length)}</b> · Cada habilidade custa 1 ponto.</p><div class="content-grid">${skills.map(([name,desc,id])=>{let got=save.skills.includes(id),can=save.level-1-save.skills.length>0;return `<article class="info-card"><span class="tag">${got?'ADQUIRIDA':can?'CUSTO · 1 PONTO':'BLOQUEADA'}</span><b>${name}</b><p>${desc}</p><button data-skill="${id}" ${got||!can?'disabled':''}>${got?'DESBLOQUEADA':can?'ADQUIRIR':'SUBA DE NÍVEL'}</button></article>`}).join('')}</div>`}
else if(activeTab==='map')c.innerHTML=`<p class="muted">MANHATTAN · REDE DE BAIRROS</p><div class="map-board">${['HELL’S KITCHEN','CHINATOWN','GREENWICH','MIDTOWN','UPPER WEST SIDE','FINANCIAL DISTRICT','CENTRAL PARK','BROOKLYN BRIDGE'].map((n,i)=>`<button data-district="${i}" class="map-district ${i===save.chapter?'selected':''}"><i></i>${n}<small>${i<=save.unlocked?'EXPLORADO':'???'}</small></button>`).join('')}</div><p class="muted">Complete capítulos e missões para revelar mais atividades.</p>`;
else if(activeTab==='stats')c.innerHTML=`<div class="content-grid">${[['NÍVEL',save.level],['EXPERIÊNCIA',`${save.xp} XP`],['CRIMINOS RESOLVIDOS',save.crimes],['PESSOAS AJUDADAS',save.rescues],['FICHAS DE PESQUISA',save.collectibles],['PONTUAÇÃO',save.score]].map(a=>`<div class="info-card"><span class="tag">REGISTRO DA CIDADE</span><b>${a[1]}</b><p>${a[0]}</p></div>`).join('')}</div>`;
else if(activeTab==='settings')c.innerHTML=`<div class="setting-row"><span>MÚSICA E EFEITOS</span><label><input id="muteToggle" type="checkbox" ${save.muted?'checked':''}> SILENCIAR</label></div><div class="setting-row"><span>VOLUME</span><input id="volumeSlider" type="range" min="0" max="100" value="${Math.round(save.volume*100)}"></div><div class="setting-row"><span>SALVAMENTO LOCAL</span><button class="inline-action" id="saveNow">SALVAR AGORA</button></div><div class="setting-row"><span>APAGAR PROGRESSO</span><button class="inline-action" id="resetSave">REINICIAR DADOS</button></div><p class="muted">O progresso é salvo neste navegador. O jogo funciona sem baixar arquivos externos.</p>`;
else c.innerHTML='<p class="muted">Uma aventura original sobre responsabilidade, coragem e as pessoas que fazem uma cidade. Personagens, história, arte e sons são criações próprias deste projeto. Desenvolvido em HTML5 Canvas, CSS e JavaScript.</p><p class="muted">ARANHA DA CIDADE · NOITE DE AÇO<br>Feito para jogar no teclado ou na tela de toque.</p>';
$$('[data-chapter]').forEach(b=>b.onclick=()=>{setScreen('cutscene');startChapter(+b.dataset.chapter)});$$('[data-side]').forEach(b=>b.onclick=()=>startSide(+b.dataset.side));$$('[data-suit]').forEach(b=>b.onclick=()=>{save.suit=+b.dataset.suit;persist();renderMenu();tone(500,.1)});$$('[data-skill]').forEach(b=>b.onclick=()=>{if(save.skills.includes(b.dataset.skill)||save.level-1-save.skills.length<1)return;save.skills.push(b.dataset.skill);persist();renderMenu();tone(600,.1)});$$('[data-district]').forEach(b=>b.onclick=()=>{if(+b.dataset.district<=save.unlocked){activeTab='chapters';renderMenu();showToast('SELECIONE UM CAPÍTULO PARA VIAJAR')}});$('#muteToggle')?.addEventListener('change',e=>{save.muted=e.target.checked;persist()});$('#volumeSlider')?.addEventListener('input',e=>{save.volume=+e.target.value/100;persist()});$('#saveNow')?.addEventListener('click',saveGame);$('#resetSave')?.addEventListener('click',()=>{if(confirm('Apagar todo o progresso salvo neste navegador?')){save={...defaults};persist();renderMenu();showToast('DADOS REINICIADOS')}})}
function startSide(i){const m=sideMissions[i];activeSide={id:i,title:m[0],target:3,reward:m[2],kind:'rescue'};menuOrigin='game';setScreen('game');objectiveCount=0;enemies=[];for(let j=0;j<5;j++)enemies.push(makeEnemy(390+j*210,false));updateHud();showToast(`MISSÃO ACEITA · ${m[0].toUpperCase()}`)}
$$('[data-pause]').forEach(b=>b.onclick=()=>{const a=b.dataset.pause;if(a==='resume')setScreen('game');if(a==='restart'){setScreen('game');enterGame()}if(a==='map'||a==='suits'){openMenu('pause',a==='map'?'map':'suits')}if(a==='save')saveGame();if(a==='home'){saveGame();setScreen('title')}});
function drawSky(){const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#0a1a2c');g.addColorStop(.58,'#263b50');g.addColorStop(1,'#111f2d');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);const moonX=W*.73,moonY=H*.21;ctx.fillStyle='#d3e2dd';ctx.globalAlpha=.72;ctx.beginPath();ctx.arc(moonX,moonY,Math.min(W,H)*.044,0,7);ctx.fill();ctx.globalAlpha=.10;ctx.beginPath();ctx.arc(moonX,moonY,Math.min(W,H)*.085,0,7);ctx.fill();ctx.globalAlpha=1;
// distant skyline
for(let layer=0;layer<3;layer++){const bw=layer===0?36:layer===1?52:72,base=groundY()+(layer-1)*25,offset=(cam*(.10+layer*.11))%bw;for(let x=-bw;x<W+bw;x+=bw){let xx=x-offset,h=80+Math.abs(Math.sin((x+layer*71)*.14))*190;ctx.fillStyle=['#17293a','#132437','#102033'][layer];ctx.fillRect(xx,base-h,bw-3,h+H-base);if(layer<2){ctx.fillStyle=layer===0?'#d79d61':'#a8c0bb';for(let wy=base-h+14;wy<base-9;wy+=14)for(let wx=xx+8;wx<xx+bw-6;wx+=12)if(Math.sin(wx*1.7+wy+gameTime*.14)>-.13){ctx.globalAlpha=.22+Math.abs(Math.sin(wx+wy))*.34;ctx.fillRect(wx,wy,3,5)}ctx.globalAlpha=1}}}
// cloud atmosphere
ctx.fillStyle='rgba(102,131,150,.08)';for(let i=0;i<4;i++){const x=((i*W*.39-gameTime*7)%(W+180)+W+180)%(W+180)-80;ctx.fillRect(x,H*.24+i*24,170,2)}}
function drawCity(){drawSky();const gy=groundY();ctx.fillStyle='#080f19';ctx.fillRect(0,gy,W,H-gy);ctx.fillStyle='#192837';ctx.fillRect(0,gy-5,W,6);ctx.fillStyle='#34434b';ctx.fillRect(0,gy+16,W,H-gy-16);ctx.fillStyle='#dcb66e';for(let x=-((cam*.8)%140);x<W;x+=140)ctx.fillRect(x,gy+66,55,3);
// foreground buildings/platform roof shapes
for(let i=-1;i<Math.ceil(W/240)+2;i++){let x=i*240-(cam%240),ht=90+Math.abs(Math.sin(i*12.23))*130;ctx.fillStyle='#0c1926';ctx.fillRect(x,gy-ht,190,ht);ctx.fillStyle='#223345';ctx.fillRect(x+6,gy-ht+7,176,ht);ctx.fillStyle='#101e2b';ctx.fillRect(x+13,gy-ht+14,160,ht);for(let wx=x+22;wx<x+155;wx+=27)for(let wy=gy-ht+30;wy<gy-15;wy+=28){ctx.fillStyle=Math.sin(wx*wy+i+gameTime*.4)>.18?'#dbac6a44':'#263b4a';ctx.fillRect(wx,wy,8,13)}ctx.fillStyle='#080f19';ctx.fillRect(x+2,gy-ht,4,ht);}
// street lamps and drifting rain
for(let x=-(cam%260)+100;x<W;x+=260){ctx.fillStyle='#263a46';ctx.fillRect(x,gy-62,3,62);ctx.fillStyle='#f0cf84';ctx.fillRect(x-4,gy-65,11,4);ctx.globalAlpha=.1;ctx.fillStyle='#f2d38b';ctx.beginPath();ctx.moveTo(x-3,gy-63);ctx.lineTo(x-36,gy);ctx.lineTo(x+36,gy);ctx.fill();ctx.globalAlpha=1}
}
function drawHero(x,y,scale=1){const px=Math.round(x),py=Math.round(y),f=player.face;ctx.save();ctx.translate(px,py);ctx.scale(f,1);const bob=Math.sin(player.anim*10)*1.5;ctx.fillStyle='#df3b48';ctx.fillRect(-7,-37+bob,14,18);ctx.fillStyle=save.suit===1?'#151d2b':save.suit===2?'#158195':save.suit===3?'#aab5bf':'#193d65';ctx.fillRect(-7,-20+bob,14,15);ctx.fillRect(-10,-19+bob,5,12);ctx.fillRect(5,-19+bob,5,12);ctx.fillStyle='#df3b48';ctx.fillRect(-8,-40+bob,16,8);ctx.fillStyle='#ecf4e9';ctx.fillRect(-5,-38+bob,4,2);ctx.fillRect(1,-38+bob,4,2);ctx.fillStyle='#111b2b';const leg=player.ground?Math.sin(player.anim*12)*3:0;ctx.fillRect(-6,-6+bob,5,8+leg);ctx.fillRect(1,-6+bob,5,8-leg);ctx.fillStyle='#d83b48';if(player.attack>0){ctx.fillRect(6,-31+bob,13,5);ctx.fillRect(17,-32+bob,4,4)}else{ctx.fillRect(6,-31+bob,5,11);ctx.fillRect(-11,-31+bob,5,10)}if(save.suit!==0){ctx.fillStyle=save.suit===2?'#76f1f0':'#f2e8de';ctx.fillRect(-2,-30+bob,4,7)}ctx.restore();}
function drawEnemy(e){const x=e.x-cam,y=groundY();if(x<-60||x>W+60)return;ctx.save();ctx.translate(Math.round(x),Math.round(y));ctx.scale(e.face,1);if(e.boss){ctx.fillStyle='#191d2a';ctx.fillRect(-20,-57,40,52);ctx.fillStyle='#9b3341';ctx.fillRect(-18,-60,36,13);ctx.fillStyle='#f3cd81';ctx.fillRect(-11,-56,6,3);ctx.fillRect(5,-56,6,3);ctx.fillStyle='#212631';ctx.fillRect(-15,-8,11,8);ctx.fillRect(5,-8,11,8);ctx.fillStyle='#6b8491';ctx.fillRect(12,-44,17,5);ctx.fillRect(25,-50,5,20);ctx.fillStyle='#e7e2d4';ctx.fillRect(-8,-47,4,2);ctx.fillRect(5,-47,4,2);ctx.fillStyle='#e4434b';ctx.fillRect(-26,-74,52,4);ctx.fillStyle='#172231';ctx.fillRect(-26,-74,52*bossHp/bossMax,4)}else{ctx.fillStyle=e.stun>0?'#36788a':'#584955';ctx.fillRect(-7,-27,14,20);ctx.fillStyle='#bb4b50';ctx.fillRect(-8,-34,16,9);ctx.fillStyle='#ded9ce';ctx.fillRect(-5,-31,3,2);ctx.fillRect(2,-31,3,2);ctx.fillStyle='#171d28';ctx.fillRect(-6,-7,5,7);ctx.fillRect(2,-7,5,7);ctx.fillStyle='#d4a36a';ctx.fillRect(6,-24,8,4)}ctx.restore();}
function update(dt){gameTime+=dt;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('#toast').classList.remove('show')}if(screen!=='game')return;const left=keys.a||keys.arrowleft,right=keys.d||keys.arrowright;if(left){player.x-=235*dt;player.face=-1;player.anim+=dt}if(right){player.x+=235*dt;player.face=1;player.anim+=dt}if(player.ground&&!left&&!right)player.anim+=dt*.4;player.x=Math.max(32,Math.min(W-45,player.x));player.vy+=1250*dt;player.y+=player.vy*dt;let gy=groundY();if(player.y>=0){player.y=0;player.vy=0;player.ground=true}player.attack=Math.max(0,player.attack-dt);player.dodge=Math.max(0,player.dodge-dt);player.invuln=Math.max(0,player.invuln-dt);player.web=Math.min(100,player.web+dt*9);cam+=(player.x+cam-W*.43)*dt*.48;cam=Math.max(0,cam);for(const e of enemies){if(e.dead)continue;e.stun=Math.max(0,e.stun-dt);e.x+=Math.sign(player.x-e.x)*((e.boss?25:38)*dt)*(e.stun?-.1:1);if(Math.abs(e.x-player.x)<40&&e.stun<=0&&player.invuln<=0&&Math.random()<dt*.8){heroHealth-=e.boss?8:5;player.invuln=.9;combo=0;burst(player.x+cam,gy-24,'#ed4b54',6);tone(70,.14,'sawtooth');if(heroHealth<=0){heroHealth=100;save.health=100;player.x=100;objectiveCount=Math.max(0,objectiveCount-1);showToast('VOCÊ CAIU · REAGRUPANDO');persist()}updateHud()}}enemies=enemies.filter(e=>!e.dead);if(!activeSide&&stage().kind!=='boss'&&stage().kind!=='free'&&enemies.length===0&&objectiveCount<stage().target){for(let i=0;i<3;i++)enemies.push(makeEnemy(player.x+cam+260+i*190,false))}particles=particles.filter(p=>p.life>0);particles.forEach(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=160*dt});if(gameTime%8<dt&&Math.random()<.35){rain.push({x:Math.random()*W,y:-10,v:350+Math.random()*240})}rain=rain.filter(r=>r.y<H);rain.forEach(r=>{r.y+=r.v*dt;r.x-=35*dt});updateHud()}
function draw(){ctx.clearRect(0,0,W,H);drawCity();const gy=groundY();for(const r of rain){ctx.strokeStyle='#92bfd333';ctx.beginPath();ctx.moveTo(r.x,r.y);ctx.lineTo(r.x-4,r.y+12);ctx.stroke()}if(screen==='title'){const heroX=W*.70,heroY=gy+1;drawHero(heroX,heroY,2);ctx.globalAlpha=.2;ctx.strokeStyle='#c9ebf1';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(heroX+20,heroY-38);ctx.quadraticCurveTo(heroX+90,H*.2,W*.84,0);ctx.stroke();ctx.globalAlpha=1;}else if(['game','pause','menu','end'].includes(screen)){// gameplay scene remains visible underneath overlays
for(const e of enemies)drawEnemy(e);drawHero(player.x,gy+player.y);for(const p of particles){ctx.globalAlpha=Math.max(0,p.life*2);ctx.fillStyle=p.color;ctx.fillRect(p.x-cam,p.y,p.size,p.size);ctx.globalAlpha=1}if(stage().kind==='boss'&&bossHp>0){ctx.fillStyle='#071322aa';ctx.fillRect(W*.34,90,W*.32,18);ctx.fillStyle='#e4434b';ctx.fillRect(W*.34+3,93,(W*.32-6)*bossHp/bossMax,12);ctx.fillStyle='#fff';ctx.font='9px monospace';ctx.textAlign='center';ctx.fillText('CHEFE · '+Math.max(0,bossHp),W*.5,86)}}else if(screen==='cutscene'){drawHero(W*.5,gy,2.1);ctx.fillStyle='#dcecf2';ctx.globalAlpha=.25;ctx.fillRect(W*.5-1,gy-160,2,130);ctx.globalAlpha=1}}
requestAnimationFrame(loop)}
function loop(t){const dt=Math.min(.04,(t-last)/1000||0);last=t;update(dt);draw()}
requestAnimationFrame(loop);
$('#titleChapter').textContent=String(save.chapter+1).padStart(2,'0');$('#levelText').textContent=String(save.level).padStart(2,'0');$('#clock').textContent=new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit'}).format(new Date());setInterval(()=>$('#clock').textContent=new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit'}).format(new Date()),30000);
})();

