1: function render(){const nav=$('#menuTabs');nav.innerHTML='';tabs.forEach(([id,label])=>{let b=document.createElement('button');b.textContent=label;b.className=id===tab?'active':'';b.onclick=()=>{tab=id;render()};nav.append(b)});$('#panelTitle').textContent=({chapters:'CAPÍTULOS',missions:'MISSÕES',suits:'TRAJES',skills:'HABILIDADES',map:'NOVA YORK',stats:'SEU LEGADO',settings:'AJUSTES',credits:'CRÉDITOS'})[tab];let c=$('#panelContent');
2: if(tab==='chapters')c.innerHTML=`<div class="chapter-list">${chapters.map((a,i)=>`<div class="chapter-row"><span>${String(i+1).padStart(2,'0')}　${a[0].toUpperCase()}</span><small>${save.completed.includes(i)?'CONCLUÍDO':i<=save.unlocked?'DISPONÍVEL':'BLOQUEADO'}</small><button data-ch="${i}" ${i>save.unlocked?'disabled':''}>${i<=save.unlocked?'JOGAR':'🔒'}</button></div>`).join('')}</div>`;
3: else if(tab==='missions')c.innerHTML=`<div class="content-grid">${side.map((a,i)=>{let done=save.completed.includes('side-'+i);return `<article class="info-card"><span class="tag">ATIVIDADE ${i+1} · ${done?'CONCLUÍDA':'DISPONÍVEL'}</span><b>${a[0]}</b><p>${a[1]}</p><button data-side="${i}" ${done?'disabled':''}>${done?'CONCLUÍDA':`ACEITAR · +${a[2]} XP`}</button></article>`}).join('')}</div>`;
4: else if(tab==='suits')c.innerHTML=`<div class="content-grid">${suits.map((a,i)=>{let ok=i===0||save.completed.includes(1)&&i===1||save.level>=3&&i===2||save.completed.includes(4)&&i===3;return `<article class="info-card"><span class="tag">${i===save.suit?'EQUIPADO':ok?'DESBLOQUEADO':'BLOQUEADO'}</span><b>${a[0]}</b><p>${a[1]} ${ok?'':`· ${a[2]}`}</p><button data-suit="${i}" ${ok?'':'disabled'}>${i===save.suit?'EM USO':ok?'EQUIPAR':'REQUISITO PENDENTE'}</button></article>`}).join('')}</div>`;
5: else if(tab==='skills'){let a=[['Punhos firmes','Ataques causam dano extra.','fight'],['Teia elástica','Recupera teia mais rápido.','web'],['Passo fantasma','Esquiva dura mais tempo.','dodge'],['Foco total','Mais vida ao concluir missões.','focus']];c.innerHTML=`<p class="muted">Pontos disponíveis: <b>${Math.max(0,save.level-1-save.skills.length)}</b> · Cada habilidade custa 1.</p><div class="content-grid">${a.map(q=>{let got=save.skills.includes(q[2]),can=save.level-1-save.skills.length>0;return `<article class="info-card"><span class="tag">${got?'ADQUIRIDA':can?'CUSTO · 1 PONTO':'BLOQUEADA'}</span><b>${q[0]}</b><p>${q[1]}</p><button data-skill="${q[2]}" ${got||!can?'disabled':''}>${got?'DESBLOQUEADA':can?'ADQUIRIR':'SUBA DE NÍVEL'}</button></article>`}).join('')}</div>`}
6: else if(tab==='map')c.innerHTML=`<p class="muted">MANHATTAN · REDE DE BAIRROS</p><div class="map-board">${chapters.slice(0,8).map((a,i)=>`<button data-district="${i}" class="map-district ${i===save.chapter?'selected':''}"><i></i>${a[1]}<small>${i<=save.unlocked?'EXPLORADO':'???'}</small></button>`).join('')}</div><p class="muted">Complete capítulos e missões para revelar atividades.</p>`;
7: else if(tab==='stats')c.innerHTML=`<div class="content-grid">${[['NÍVEL',save.level],['EXPERIÊNCIA',save.xp+' XP'],['CRIMINOS RESOLVIDOS',save.crimes],['PESSOAS AJUDADAS',save.rescues],['FICHAS DE PESQUISA',save.collectibles],['PONTUAÇÃO',save.score]].map(a=>`<div class="info-card"><span class="tag">REGISTRO DA CIDADE</span><b>${a[1]}</b><p>${a[0]}</p></div>`).join('')}</div>`;
8: else if(tab==='settings')c.innerHTML=`<div class="setting-row"><span>MÚSICA E EFEITOS</span><label><input id="muteToggle" type="checkbox" ${save.muted?'checked':''}> SILENCIAR</label></div><div class="setting-row"><span>VOLUME</span><input id="volumeSlider" type="range" min="0" max="100" value="${Math.round(save.volume*100)}"></div><div class="setting-row"><span>SALVAMENTO LOCAL</span><button class="inline-action" id="saveNow">SALVAR AGORA</button></div><div class="setting-row"><span>APAGAR PROGRESSO</span><button class="inline-action" id="resetSave">REINICIAR DADOS</button></div><p class="muted">O progresso é guardado neste navegador.</p>`;
9: else c.innerHTML='<p class="muted">Uma aventura original sobre responsabilidade, coragem e as pessoas que fazem uma cidade. Personagens, história, arte e sons são criações próprias deste projeto. HTML5 Canvas, CSS e JavaScript.</p><p class="muted">ARANHA DA CIDADE · NOITE DE AÇO</p>';
10: all('[data-ch]').forEach(b=>b.onclick=()=>start(+b.dataset.ch));all('[data-side]').forEach(b=>b.onclick=()=>startSide(+b.dataset.side));all('[data-suit]').forEach(b=>b.onclick=()=>{save.suit=+b.dataset.suit;persist();render()});all('[data-skill]').forEach(b=>b.onclick=()=>{if(!save.skills.includes(b.dataset.skill)&&save.level-1-save.skills.length>0){save.skills.push(b.dataset.skill);persist();render()}});all('[data-district]').forEach(b=>b.onclick=()=>{if(+b.dataset.district<=save.unlocked){tab='chapters';render();msg('ESCOLHA UM CAPÍTULO')}});$('#muteToggle')?.addEventListener('change',e=>{save.muted=e.target.checked;persist()});$('#volumeSlider')?.addEventListener('input',e=>{save.volume=+e.target.value/100;persist()});$('#saveNow')?.addEventListener('click',()=>{save.health=hp;persist();msg('PROGRESSO SALVO')});$('#resetSave')?.addEventListener('click',()=>{if(confirm('Apagar todo o progresso salvo neste navegador?')){save={...base};persist();render();msg('DADOS REINICIADOS')}})}
11: function startSide(i){let a=side[i];active={id:i,title:a[0],reward:a[2]};origin='game';set('game');count=0;enemies=[];for(let j=0;j<5;j++)enemies.push(enemy(390+j*210));updatehud();msg(`MISSÃO ACEITA · ${a[0].toUpperCase()}`)}
12: all('[data-pause]').forEach(b=>b.onclick=()=>{let a=b.dataset.pause;if(a==='resume')set('game');if(a==='restart')enter();if(a==='map'||a==='suits')openMenu('pause',a);if(a==='save'){save.health=hp;persist();msg('PROGRESSO SALVO')}if(a==='home'){save.health=hp;persist();set('title')}});

