@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=DM+Mono:wght@400;500&display=swap');
:root {
--ink:#071322;--paper:#edf3f4;--muted:#a0b0bb;--red:#e4434b;--cyan:#59d5e5;--line:rgba(222,239,244,.19);--mono:'DM Mono',monospace;--display:'Barlow Condensed',Impact,sans-serif}
* {
box-sizing:border-box}
html,body {
height:100%;margin:0;background:#071322;color:var(--paper);font-family:var(--mono);overflow:hidden}
button {
font:inherit;color:inherit;cursor:pointer}
#app {
position:relative;width:100%;height:100%;min-height:520px;overflow:hidden;background:radial-gradient(ellipse at 68% 35%,#263d55 0,#101f31 44%,#071322 100%);isolation:isolate}
#scene {
position:absolute;inset:0;width:100%;height:100%;image-rendering:pixelated;z-index:-1}
.scanlines {
position:absolute;inset:0;pointer-events:none;z-index:5;opacity:.10;background:repeating-linear-gradient(0deg,transparent 0px,transparent 3px,#b6d2d8 4px);mix-blend-mode:soft-light}
.topbar {
position:absolute;z-index:4;left:5.2%;right:5.2%;top:5%;display:flex;align-items:center;justify-content:space-between;font-size:10px;letter-spacing:.13em;color:#dbe5e8}
.brand {
font-family:var(--display);font-size:21px;font-weight:600;letter-spacing:.08em}
.brand b {
font-weight:900;color:#fff}
.brand-mark {
display:inline-grid;place-items:center;width:27px;height:27px;margin-right:10px;color:var(--red);border:1px solid rgba(228,67,75,.7);font-size:15px;vertical-align:middle}
.top-meta {
display:flex;align-items:center;gap:8px;color:#aebdc7}
.pulse {
width:7px;height:7px;border-radius:50%;background:#df5556;box-shadow:0 0 11px #ed5353}
.edition {
padding:7px 9px;border:1px solid var(--line);margin-left:13px;font-size:9px;letter-spacing:.12em}
.screen {
position:absolute;inset:0;z-index:2}
.title-screen {
background:linear-gradient(90deg,rgba(5,14,25,.75) 0%,rgba(5,14,25,.25) 44%,transparent 75%),linear-gradient(0deg,rgba(4,11,20,.75),transparent 30%)}
.title-copy {
position:absolute;left:11.2%;top:25%;max-width:470px}
.eyebrow {
font-size:10px;letter-spacing:.23em;color:var(--cyan);font-weight:500}
.title-copy h1 {
font:900 clamp(76px,10.5vw,142px)/.73 var(--display);letter-spacing:-.025em;margin:28px 0 20px;text-shadow:5px 5px 0 rgba(5,15,27,.5)}
h1 em {
font-style:normal;color:var(--red)}
.intro-copy {
font-size:12px;color:#c0cbd2;letter-spacing:.015em;margin-bottom:34px}
.title-actions {
display:flex;gap:12px}
.primary,.secondary {
min-height:47px;padding:0 20px;border:1px solid var(--red);background:var(--red);font-size:10px;letter-spacing:.1em;font-weight:500;transition:.2s}
.primary span,.secondary span {
font-size:16px;margin-left:19px}
.primary:hover {
background:#ff6268;transform:translateY(-2px);box-shadow:0 7px 30px #e4434b42}
.secondary {
border-color:rgba(255,255,255,.35);background:rgba(9,20,33,.3)}
.secondary:hover {
border-color:#fff;background:#ffffff14}
.tiny-note {
margin-top:19px;font-size:8px;letter-spacing:.14em;color:#778a98}
.hero-caption {
position:absolute;right:9%;bottom:16%;display:flex;gap:14px;align-items:center}
.hero-caption>span {
