.map-board {
display:grid;grid-template-columns:repeat(4,1fr);gap:8px;padding:12px;background:linear-gradient(135deg,#102338,#142a3b);border:1px solid #ffffff15}
.map-district {
min-height:75px;border:1px solid #ffffff18;background:#081727;color:#d9e3e7;font:600 10px var(--display);letter-spacing:.07em;padding:8px;position:relative}
.map-district i {
display:block;width:8px;height:8px;margin:0 auto 8px;border-radius:50%;background:#59d5e5;box-shadow:0 0 9px #59d5e5}
.map-district small {
display:block;color:#91a5b1;font:7px var(--mono);margin-top:5px}
.map-district.selected {
border-color:var(--red);background:#e4434b19}
.map-district:disabled {
opacity:.45}
.pause-panel {
width:min(540px,90vw);text-align:center}
.pause-panel h2 {
font-size:62px;margin-bottom:2px}
.pause-grid {
display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:24px 0}
.pause-grid button {
display:flex;justify-content:space-between;padding:13px 14px;background:#ffffff08;border:1px solid #ffffff1a;text-align:left;font-size:9px;letter-spacing:.08em}
.pause-grid button:hover {
border-color:var(--red)}
.pause-grid button span {
font-size:14px;color:var(--cyan)}
.controls-hint {
font-size:8px;line-height:1.8;color:#8da0ab}
.cutscene {
z-index:9;background:#071322ed;display:flex;flex-direction:column;justify-content:space-between;padding:5.5% 8%;animation:fadein .5s}
.cutscene-top {
display:flex;justify-content:space-between;font-size:9px;letter-spacing:.16em}
.cutscene-top button {
background:none;border:0;color:#a9bac4;font-size:9px;letter-spacing:.12em}
.cutscene-text {
max-width:620px;margin:0 auto;text-align:center}
.cutscene-text h2 {
font:800 clamp(42px,8vw,82px)/.9 var(--display);margin:14px 0}
.cutscene-text>p:not(.eyebrow) {
color:#bdc8ce;font-size:12px;line-height:1.8;min-height:35px}
.cutscene-text button {
margin-top:22px}
.scene-progress {
height:2px;background:#283744}
.scene-progress i {
height:100%;width:0;display:block;background:var(--red);transition:width .4s}
.ending-panel {
text-align:center}
.ending-panel .primary,.ending-panel .secondary {
margin:8px}
.reward-line {
font-size:10px;color:var(--cyan);letter-spacing:.1em;margin:24px}
.ending-panel h2 {
font-size:56px}
.ending-panel .muted {
max-width:460px;margin:0 auto}
@keyframes fadein {
