import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const root='/home/runner/.local/share/omgithub-playwright'; const require=createRequire(root+'/package.json'); const {chromium}=require('playwright');
process.env.DISPLAY=':'+readFileSync(root+'/display','utf8').trim(); const config=JSON.parse(readFileSync(root+'/linux.json','utf8'));
const browser=await chromium.launch(config.browser.launchOptions); const errors=[];
try {const context=await browser.newContext({viewport:{width:390,height:844},isMobile:true,hasTouch:true}); const p=await context.newPage(); p.on('pageerror',e=>errors.push(e.message)); p.on('console',m=>{if(m.type()==='error')errors.push(m.text())}); await p.goto('http://127.0.0.1:8765');
 await p.locator('#newGame').tap(); await p.locator('#skipScene').tap();
 console.log('TOUCH HUD', await p.locator('#touchControls').isVisible(), 'box',await p.locator('#touchControls').boundingBox());
 const before=await p.locator('#webFill').evaluate(e=>e.getBoundingClientRect().width);
 await p.locator('[data-action="web"]').tap(); await p.waitForTimeout(100);
 const after=await p.locator('#webFill').evaluate(e=>e.getBoundingClientRect().width);
 console.log('WEB BUTTON',before,after,'TOAST',await p.locator('#toast').innerText());
 await p.locator('[data-action="right"]').tap(); await p.locator('[data-action="attack"]').tap();
 await p.locator('#pauseButton').tap(); console.log('PAUSE',await p.locator('#pauseScreen').isVisible());
 await p.screenshot({path:'/tmp/opencode/mobile-game.png'});
 console.log('ERRORS',JSON.stringify(errors)); await context.close();
} finally {await browser.close()}
EOF
